"use client";
/* Thread, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Thread(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("thread"); }, []);
  return React.createElement("piix-pal", { "pal": "thread", ...piixAttrs(props) });
}

export default Thread;
